Design a thermometer decoder that converts a 5-bit binary input (Bin) into a 32-bit one-hot encoded output (Bout). The output will have a '1' at each position from 0 up to the value represented by the input, and '0' elsewhere. For example, if Bin represents the binary value 3, then the output Bout will have '1's in the first four bits (positions 0 to 3) and '0's in the rest.
module top_module(

   input  wire [4:0]  Bin,      
   output reg  [31:0] Bout      

   ) ;

code:
module top_module(

   input  wire [4:0]  Bin,      
   output reg  [31:0] Bout      

   ) ;integer i ;

   always @(*) begin

      for(i=0; i < 32; i=i+1) begin

         Bout[i] = (Bin[4:0] >= i) ;      

      end  
   end  

endmodule

