    input       rst_n,
    input       btn_in,
    output reg  btn_out
);

    reg [3:0] counter;
    reg btn_in_d;

    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            counter <= 4'b0;
            btn_out <= 1'b0;
            btn_in_d <= 1'b0;
        end
        else begin
