description:
Design a circuit that counts the number of '1' bits in a 4-bit binary input and outputs the count using a 3-bit wide output. The module utilizes a combinational logic structure, specifically a case statement, to determine the population count for all possible inputs, providing the correct count of '1's from 0 to 4.
module top_module(
    input [3:0] in,
    output reg [2:0] pCount
    );

code:
module top_module(
    input [3:0] in,
    output reg [2:0] pCount
    );always@(*) begin
		case(in)
		0: begin
			pCount <= 0;
		end
		1: begin
			pCount <= 1;
		end
		2: begin
			pCount <= 1;
		end
		3: begin
			pCount <= 2;
		end
		4: begin
			pCount <= 1;
		end
		5: begin
			pCount <= 2;
		end
		6: begin
			pCount <= 2;
		end
		7: begin
			pCount <= 3;
		end
		8: begin
			pCount <= 1;
		end
		9: begin
			pCount <= 2;
		end
		10: begin
			pCount <= 2;
		end
		11: begin
			pCount <= 3;
		end
		12: begin
			pCount <= 2;
		end
		13: begin
			pCount <= 3;
		end
		14: begin
			pCount <= 3;
		end
		15: begin
			pCount <= 4;
		end
		default: begin
			pCount <= 0;
		end
		endcase
	 end

endmodule

