module top_module(
  input [31:0] a,
  input [31:0] b,
  input [1:0] mode,
  output [31:0] add_out,
  output [31:0] sub_out,
  output [31:0] mul_out,
  output [31:0] div_out
);wire [31:0] add;
  wire [31:0] sub;
  wire [31:0] mul;
  wire [31:0] div;

  assign add = a + b;
  assign sub = a - b;
  assign mul = a * b;
  assign div = a / b;

