        $finish;
    end

    // Task to check outputs
    task check_outputs;
        input [31:0] expected_column;
        input expected_push_out;
        input [31:0] expected_row;
        input [63:0] expected_value;
        begin
            if (expected_column === (expected_column ^ column ^ expected_column) &&
